// Generated from the individually edited RU event-outcomes catalog (E101-E150).
// Literary strings only. Gameplay mechanics stay in events-core.mjs.
const OUTCOMES_E101_E150 = Object.freeze({"E101.1":{"s":"Мейр снимает с Маргариты красную попону и вручает поводок, будто передаёт крепость. Коза тут же съедает край дорожного мешка, зато оставляет отряду съестные запасы."},"E101.2":{"s":"Пострадавшие огородники получают возмещение, а Мейр ставит на жалобах печать «урегулировано». Маргарита немедленно направляется к четвёртому огороду."},"E101.3":{"s":"{{heroName}} находит в указе лазейку: достоинство Маргариты неприкосновенно, но счета за капусту не являются государственными. Обрадованные крестьяне возвращают в казну часть прежде удержанных денег.","f":"{{heroName}} зачитывает уточнение, но Мейр предъявляет заверенную копию указа с ещё худшими формулировками. За попытку пересмотра деревня взыскивает судебные расходы."},"E101.4":{"s":"Староста записывает Маргариту единственной должницей по собственным счетам. Коза блеет, но больше никто не требует денег с королевского кошеля.","f":"При попытке взыскать долг с козы её защитники объявляют это оскорблением трона. На площади начинается стычка."},"E101.5":{"s":"Вы оставляете Мейра разбираться с королевской козой по местным законам. Последнее, что слышно за мостом, — требование оплатить ещё один куст капусты."},"E102.1":{"s":"Первый пристав принимает девочку под расписку и вручает предусмотренную приказом награду. Она уносит коробку с собой, не простившись.","f":"Первый пристав тянется за коробкой, но девочка отступает и требует показать второй приказ. Передача срывается, и отряд остаётся без награды."},"E102.2":{"s":"Второй пристав берёт девочку под охрану и выдаёт припасы на дорогу. Напоследок она крепче прижимает к себе закрытую коробку.","f":"Первый пристав преграждает путь сопернику, заявляя о нарушении королевского распоряжения. Спор переходит в стычку."},"E102.3":{"s":"{{heroName}} сопоставляет подписи и находит запись о замене распоряжения в пути. За разоблачение подмены отряд получает золото, а девочку передают по действительному приказу.","f":"{{heroName}} доказывает лишь то, что оба приказа подлинные; установить, какой из них должен действовать, не удаётся. Девочка остаётся с коробкой под присмотром спорящих приставов."},"E102.4":{"s":"Вы сажаете девочку рядом с возницей и обещаете довезти до ближайшего города без приставов. На дополнительного пассажира уходят припасы."},"E102.5":{"s":"В коробке лежит свидетельство с печатями обоих ведомств и спрятанный кошель. Найденное золото поступает в казну, а девочка молча захлопывает крышку.","f":"Девочка успевает крикнуть, когда вы срываете крышку, и оба пристава обвиняют отряд в похищении улики. Начинается стычка."},"E103.1":{"s":"Король признаёт давнюю волю земли, и говорящий камень впервые замолкает с явным удовлетворением. Рудек благодарит отряд мешками свежего урожая."},"E103.2":{"s":"Гастон получает законное подтверждение сделки и отсчитывает плату за решение. Камень у дороги недовольно скребёт по мостовой, но границы остаются на бумаге."},"E103.3":{"s":"Дух соглашается перенести межу к старому ручью, оставив Рудеку часть пашни. Гастон платит за завершённую сделку и делится дорожными припасами.","f":"На предложенной новой границе столбы за ночь снова оказываются по-старому. Камень отказывается обсуждать другие участки."},"E103.4":{"s":"Вы выкапываете камень, и Гастон платит за доставленного свидетеля. Тот всю дорогу ворчит, что переезд тоже должен быть оформлен по закону.","f":"Едва лопаты касаются камня, из земли поднимаются его защитники. Вместо суда начинается стычка."},"E103.5":{"s":"Вы оставляете Гастона, Рудека и говорящий камень спорить о праве собственности. За спиной раздаётся требование пригласить нотариуса, умеющего слушать землю."},"E104.1":{"s":"Вы помогаете Освальду выровнять края могилы и делите с ним ужин. Старик благодарит за работу золотом и обещает не ложиться туда раньше срока."},"E104.2":{"s":"Освальд откладывает лопату: клятву товарищу можно исполнить и позже. Он забирает меч и идёт с вашим отрядом.","f":"Освальд отказывается от похода, но достаёт из старых запасов провизию на дорогу. «Хоронить рано, а кормить гостей — вовремя», — говорит он.","v":{"rs":"Освальд уже готов забрать меч, но принять нового бойца не получается. Старик передаёт золото и возвращается к своей могиле."}},"E104.3":{"s":"{{heroName}} выслушивает Тимо наедине, и тот наконец решается спорить с дядей не о могиле, а о завтрашнем дне. В благодарность племянник отдаёт дорожные припасы.","f":"{{heroName}} пытается разговорить Тимо, но тот отвечает, что уже сказал дяде всё необходимое. Отряд уходит без подарков."},"E104.4":{"s":"Священник отмечает место для Освальда в кладбищенской книге и принимает плату. Старик выглядит довольным: теперь можно спокойно жить дальше."},"E104.5":{"s":"Вы не вмешиваетесь в обещание, данное двадцать лет назад. Освальд продолжает копать, а Тимо сидит рядом, демонстративно сложив руки."},"E105.1":{"s":"Вы разбираете кусок стены там, где изнутри слышен стук, и открываете проход к корчме. Гельм выдаёт обещанный ужин и припасы.","f":"Первые же камни падают внутрь, и приходится остановиться, чтобы не задеть посетителей. На бесполезные работы уходят припасы."},"E105.2":{"s":"Вы находите на стене скрытый узор и снимаете чары, прятавшие проём. Гельм благодарит за спасение выручкой из кассы.","f":"Когда вы касаетесь узора, стена отвечает ударом, и {{affectedHeroName}} получает тяжёлое ранение. Вход так и не появляется.","v":{"nf":"Чары на стене срабатывают, но среди доступных бойцов никто не получает тяжёлого ранения. Проём остаётся невидимым."}},"E105.3":{"s":"{{heroName}} находит безопасную точку в кладке, и вместо третьего удара в стене открывается проём. Трактирщик выдаёт золото и дорожный ужин.","f":"{{heroName}} обнаруживает, что перестраивать стену сейчас опасно: за ней проходят несущие балки. Вход отряд так и не открывает."},"E105.4":{"s":"Постояльцы по очереди выбираются из окон, а Гельм последним выталкивает мешок с едой в благодарность. Изнутри снова доносится стук, но ночевать там уже некому."},"E105.5":{"s":"Утром в стене обнаруживается обычная дверь, словно никогда и не исчезала. Гельм хватает её за ручку прежде, чем она передумает.","f":"Ночью из глухой стены выходят вооружённые существа, которых посетители корчмы не видели. Отряду приходится начать стычку."},"E106.1":{"s":"Король объявляет одно состязание вместо двадцати семи отдельных ухаживаний, и мост наконец освобождается. Секретарь Эд оплачивает организацию золотом.","f":"Проигравшие женихи обвиняют судей в пристрастности и перекрывают дорогу щитами. Начинается стычка."},"E106.2":{"s":"Лисса благодарит за мысль, что отсутствие жениха тоже может быть решением, и открывает проезд. На дорожку отряд получает припасы.","f":"Лисса принимает совет за публичное оскорбление и требует возмещения за сорванный смотр. Отряду приходится отдать золото."},"E106.3":{"s":"{{heroName}} велит каждому жениху самостоятельно решить, что делать с собственной очередью. Большинство немедленно разъезжается, а Эд платит за освобождённый мост.","f":"{{heroName}} предлагает испытание, но претенденты начинают спорить о правилах ещё до его начала. Дорога остаётся заставленной тележками."},"E106.4":{"s":"Один из женихов решает, что поход — лучшее место для самостоятельных решений, и записывается в ваш отряд.","f":"Самый толковый претендент вежливо отказывается: он приехал жениться, а не записываться в дружину.","v":{"rs":"Жених охотно сменил бы турнир на поход, но взять нового бойца нельзя. Вместо службы он благодарит отряд золотом."}},"E106.5":{"s":"Вы сворачиваете к броду, расходуя припасы на длинный обход. За спиной двадцать семь голосов одновременно спрашивают, какой конь лучше."},"E107.1":{"s":"Король вскрывает конверт и находит перечень старых дорожных схронов. По одной из подсказок отряд добывает припасы.","f":"Бумага обжигает ладони Короля прежде, чем он успевает прочесть первую строку. Он получает тяжёлое ранение.","v":{"nf":"Печать письма вспыхивает в руках Короля, но тяжёлого ранения не происходит. Содержимое остаётся неразобранным."}},"E107.2":{"s":"Вы поджигаете конверт, и из пепла выпадают старые золотые монеты, скрытые в печати. Ильве не пытается остановить вас.","f":"Огонь не берёт бумагу; вместо этого возле павильона появляются вооружённые хранители письма. Начинается стычка."},"E107.3":{"s":"{{heroName}} разрывает связь между печатью и читающим, не вскрывая конверта. Ильве платит золотом за освобождение от многолетней опасности.","f":"{{heroName}} видит, что чары зацеплены за каждое слово письма, и не рискует разрывать их вслепую. Конверт остаётся запечатанным."},"E107.4":{"s":"Вы оставляете письмо на столе, где оно пролежало сто девяносто лет. Ильве снова запирает павильон и гасит свет."},"E108.1":{"s":"Вы проверяете следы рубки и записи о конфискации, а не выбор Аэра. Стороны принимают выводы, и торговец платит за разбирательство.","f":"Свидетели противоречат друг другу, а лесничие не предоставляют опись деревьев. Суд возвращается к оленю без решения."},"E108.2":{"s":"Аэр идёт за яблоками к выбранной дощечке, и спорящие эльфы принимают это за вердикт. За услугу вам достаётся золото.","f":"Олень съедает яблоки вместе с дощечкой и остаётся на месте. Припасы потрачены, а решение так и не принято."},"E108.3":{"s":"В древесине обнаруживаются следы живой магии, подтверждающие нарушение запрета. Лесничие отдают припасы за помощь в расследовании.","f":"Проверка портит часть проб и расходует припасы, но ничего определённого не показывает. Обвинения остаются прежними."},"E108.4":{"s":"Вы объявляете, что Аэр своим молчанием предлагает мир, и стороны делят спорный груз по соглашению. За посредничество вам выплачивают золото.","f":"Торговец требует письменного вердикта, а лесничие ждут от оленя хотя бы одного шага. Мировое соглашение не складывается."},"E108.5":{"s":"Вы оставляете двух эльфов ждать решения Аэра. Олень уже жуёт угол последней дощечки."},"E109.1":{"s":"Вы находите слова, которые Маэрин давно пыталась вспомнить, и бук раскрывает старое дупло. Внутри лежит золото, оставленное её матерью.","f":"Последняя строчка выходит неверной, и корни крепче обхватывают старый сундук. Маэрин просит больше не петь наугад."},"E109.2":{"s":"Вы разрубаете сухие корни и вынимаете сундук из дупла. Золото уходит в казну, хотя Маэрин не радуется такому решению.","f":"Бук поднимает корни вокруг топоров, а из леса приходят его защитники. Начинается стычка."},"E109.3":{"s":"{{heroName}} считывает остатки мелодии из памяти бука, и Маэрин впервые допевает её целиком. Дерево открывает сундук с золотом и дорожными припасами.","f":"{{heroName}} различает лишь первые такты забытой песни; дерево не отвечает на попытку восстановить конец. Сундук остаётся закрытым."},"E109.4":{"s":"Маэрин соглашается, что незаконченная песня тоже хранит память о матери. Она делится с отрядом припасами и остаётся у дерева.","f":"Маэрин просит не лишать её последней надежды услышать песню полностью. Вы уходите без подарка."},"E109.5":{"s":"Вы оставляете Маэрин наедине с буком и недопетой мелодией. Ещё долго слышно, как ветви повторяют оборванную строку."},"E110.1":{"s":"Вы выбираете старую дорогу без единого замечания о новой. Тропа ведёт длинным путём, поэтому часть припасов уходит на переход."},"E110.2":{"s":"Вы расхваливаете тропу, и та подводит отряд к короткому проходу с оставленным путниками запасом еды. Припасов становится больше.","f":"Тропа слышит похвалу, но не меняет направление ни на шаг. Короткого пути и награды нет."},"E110.3":{"s":"{{heroName}} вырывается вперёд, и тропа с шумом перестраивается под быстрый ход. На неожиданном повороте отряд находит золото.","f":"Тропа резко загибается под ногами всадника, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Тропа меняет направление слишком резко, но среди доступных бойцов никто не получает тяжёлого ранения. Обещанного короткого пути нет."}},"E110.4":{"s":"Вы прорубаете собственную просеку и выходите к дороге, не обращая внимания на недовольный шорох позади.","f":"Пока вы расчищаете просеку, лес выставляет вооружённых защитников чужой тропы. Начинается стычка."},"E110.5":{"s":"Вы возвращаетесь к развилке и выбираете другой маршрут. Эрен просит не оглядываться, когда старая тропа начинает шуршать."},"E111.1":{"s":"Отряд идёт на свист и находит покинутый охотничий привал с целыми запасами. Сиэль узнаёт стрелы брата, но самого его среди деревьев нет.","f":"Свист раздаётся со всех сторон, и чаща смыкается вокруг бойцов. Из укрытий выходят вооружённые охотники леса — начинается битва."},"E111.2":{"s":"Огонь выгоняет из зарослей тех, кто прятался у старого тайника охотников. Не вступая в бой, отряд забирает оставленное золото.","f":"На дым отвечают не пропавшие товарищи Сиэль, а вооружённые хозяева чащи. У костра начинается стычка."},"E111.3":{"s":"{{heroName}} осматривает верхние ветви и обнаруживает скрытый привал с припасами. Следы охотников обрываются там, но запас удаётся забрать.","f":"Между ветвями срабатывает старая петля, и {{affectedHeroName}} получает тяжёлое ранение. Поиск приходится прекратить.","v":{"nf":"Ловушка в кронах срывает разведку, но никто из допустимых бойцов не получает тяжёлого ранения. След пропавших теряется."}},"E111.4":{"s":"Сиэль соглашается не отправлять за братом новых людей без подготовки. Она благодарит отряд золотом и снимает со стены один из пустых колчанов.","f":"Сиэль отказывается уходить: она снова слышит знакомый свист и хватает лук. Убедить её не удаётся."},"E111.5":{"s":"Вы оставляете Сиэль у развешенных луков. Свист из леса повторяется, но отряд уже выходит на дорогу."},"E112.1":{"s":"Финн достаёт спрятанное письмо с волей хозяйки, и наследники наконец видят её решение о разделе. За восстановленное завещание отряду выплачивают золото.","f":"Финн пугается угроз и заявляет, что письмо утрачено. Наследники требуют с вас возмещения за бесплодное разбирательство."},"E112.2":{"s":"Вы признаёте все три ветви знаком воли матери, и наследники соглашаются разделить землю. Финн снабжает отряд припасами в благодарность.","f":"Двое наследников обвиняют третьего в подкупе садовника и хватаются за оружие. Начинается стычка."},"E112.3":{"s":"{{heroName}} предлагает каждому наследнику объявить свою долю самостоятельным владением. Никому не приходится признавать поражение, а отряду платят золотом и провизией.","f":"{{heroName}} предлагает условия, но наследники спорят о старшинстве даже при равном разделе. Договор не заключён."},"E112.4":{"s":"Наутро молодое дерево вновь тянет три ветви к спорщикам. Наследники признают знак и в благодарность отдают золото.","f":"За ночь ветви переплетаются так, что никто не может указать свою. Семейный спор продолжается без решения."},"E112.5":{"s":"Вы отказываетесь решать судьбу чужого поместья без достаточных оснований. Финн остаётся между наследниками и деревом с тремя ветвями."},"E113.1":{"s":"Браг и его товарищи выполняют порученные работы с неожиданным усердием. За починку перехода они оставляют отряду собранные припасы."},"E113.2":{"s":"Вождь забирает пятерых «пленных» и расплачивается золотом, не задавая вопросов. Браг с тоской смотрит на дорогу обратно к лагерю.","f":"Браг понимает, куда его ведут, и поднимает товарищей на сопротивление. Начинается стычка."},"E113.3":{"s":"Браг первым вызывается служить Королю, если это избавит его от выгребных ям. Один из орков вступает в отряд.","f":"Орки решают, что поход слишком похож на службу вождю, и отказываются. В качестве извинения они оставляют немного провизии.","v":{"rs":"Браг согласен служить, но нового бойца принять не удаётся. Орки благодарят за предложение золотом и уходят искать другой способ избежать наказания."}},"E113.4":{"s":"Вы предлагаете вождю заменить наказание настоящим испытанием для пятерых бойцов. Орки одобрительно ревут и платят золотом за совет.","f":"Браг и его друзья отвергают каждое испытание, в котором нужно работать. Уговорить их не получается."},"E113.5":{"s":"Вы возвращаете Брагу его топор и велите пятерым немедленно идти к вождю. Орки строятся так понуро, будто уже слышат звук лопат."},"E114.1":{"s":"Король ударяет в барабан, и над лагерем наконец проходит настоящий дождь. Благодарные орки снабжают отряд провизией.","f":"После удара барабана вместо дождя появляются вооружённые незваные гости. Урх прячет палочки: начинается битва."},"E114.2":{"s":"Вы объясняете Урху, как найти подземную воду и вырыть колодец без всяких заклинаний. Шаман платит золотом за идею.","f":"Урх внимательно выслушивает совет и спрашивает, кто будет копать. На этом обсуждение колодца заканчивается."},"E114.3":{"s":"{{heroName}} меняет местами неверно начертанные руны, и барабан вызывает обычный дождь. Урх награждает отряд золотом и припасами.","f":"{{heroName}} пробует восстановить руны, но барабан поглощает приготовленные материалы. Припасов становится меньше, дождя нет."},"E114.4":{"s":"Вы оплачиваете барабан, и Урх передаёт его без обещаний относительно погоды. Орки выглядят подозрительно довольными сделкой."},"E114.5":{"s":"Вы покидаете орочий лагерь, пока Урх снова натягивает кожу на барабан. Вслед раздаётся звук, удивительно похожий на чиновничий кашель."},"E115.1":{"s":"Вы отдаёте Гарре золото за выбитый зуб, и она торжественно объявляет долг Пика закрытым. Молодой орк впервые за день закрывает рот."},"E115.2":{"s":"Поединок заканчивается первой царапиной, и Гарра принимает исход как честную компенсацию. За устроенное разбирательство вам отдают золото.","f":"Тренировочный спор превращается в настоящий удар: {{affectedHeroName}} получает тяжёлое ранение. Обычай оказывается куда опаснее зуба.","v":{"nf":"Поединок срывается прежде, чем кто-либо из допустимых бойцов получает тяжёлое ранение. Гарра по-прежнему требует компенсации."}},"E115.3":{"s":"{{heroName}} предлагает Пику возместить зуб работой на Гарру, не унижая ни одного из них. Орки соглашаются и снабжают отряд припасами.","f":"{{heroName}} предлагает примирение, но Гарра требует сначала услышать от Пика извинения. Спор остаётся открытым."},"E115.4":{"s":"Пик решает отработать долг службой вдали от тренировочной площадки и присоединяется к отряду.","f":"Гарра не соглашается считать чужую службу оплатой её зуба. Пик остаётся у костра и продолжает спор.","v":{"rs":"Пик готов уйти в поход, но места для нового бойца нет. Вместо службы орки выдают отряду небольшую денежную благодарность."}},"E115.5":{"s":"Вы оставляете Гарру и Пика спорить о справедливой цене одного зуба. К вашему уходу предложение уже выросло до трёх."},"E116.1":{"s":"Вы объясняете юному орку, какое имя услышала Ома, и предлагаете ему решать самому. Он кладёт ладонь на камень ещё раз, уже не пряча дрожь.","f":"Подросток принимает рассказ за попытку унизить его перед кланом и уходит от камня. Ома так и не завершает ритуал."},"E116.2":{"s":"Вы называете нейтральное имя, и Ома завершает обряд, не выдавая шёпот камня. Благодарная старейшина передаёт золото.","f":"Камень вслух повторяет запретное имя, разоблачая подмену. На попытки успокоить собравшихся уходят припасы."},"E116.3":{"s":"{{heroName}} отделяет древнее эхо камня от живого голоса подростка. Ома проводит ритуал заново и награждает отряд припасами.","f":"{{heroName}} не может понять, принадлежит ли шёпот камню или памяти старейшины. Ома откладывает обряд."},"E116.4":{"s":"Вы разбиваете чёрный камень и находите внутри старые золотые пластины. Подросток впервые слышит тишину вместо чужого имени.","f":"Удар по камню поднимает клановых хранителей, которые считают разрушение святотатством. Начинается битва."},"E116.5":{"s":"Вы оставляете Ому и подростка перед Камнем Имени. Старейшина ещё раз склоняется к его поверхности, но не произносит ни слова."},"E117.1":{"s":"Вы обращаетесь к Клыку как к капитану, и волк важно пропускает отряд к реке. Тург благодарит вас припасами за то, что никто не оспорил устав.","f":"Клык отказывается принимать чужие переговоры и уводит патруль за подозрительной белкой. Ни прохода по договорённости, ни награды вы не получаете."},"E117.2":{"s":"Волк соглашается обменять капитанский знак на мясо, и Тург возвращает себе командование. Он платит золотом за спасённую должность."},"E117.3":{"s":"{{heroName}} опускается на уровень волчьих глаз и жестами убеждает Клыка пропустить отряд. Тург выдаёт припасы, пока капитан занят новым следом.","f":"{{heroName}} неверно понимает короткий рык и получает в ответ только требование не подходить к ящику. Договор не состоялся."},"E117.4":{"s":"Вы выдерживаете взгляд Клыка дольше, чем он выдерживает ваш. Тург объявляет законную победу и благодарит золотом.","f":"Клык внезапно бросается на участника игры, и {{affectedHeroName}} получает тяжёлое ранение. Патруль по-прежнему подчиняется волку.","v":{"nf":"Игра заканчивается опасным рывком Клыка, но никто из допустимых бойцов не получает тяжёлого ранения. Капитанский знак остаётся у волка."}},"E117.5":{"s":"Вы не вмешиваетесь в командование орочьего патруля. Клык спрыгивает с ящика и ведёт солдат по следу белки."},"E118.1":{"s":"Вы отдаёте золото за пленника до восхода солнца, и обе семьи принимают сделку. Оправившись, солдат решает служить в вашем отряде.","v":{"rs":"Вы выкупаете раненого солдата, но принять бойца в отряд нельзя. Он оставляет золото в благодарность за спасение."}},"E118.2":{"s":"Вы напоминаете обеим семьям, что гость ещё не успел рассказать свою историю. Они продлевают защиту и дают вам припасы за посредничество.","f":"Семьи обвиняют отряд в нарушении обычая и начинают спорить с оружием в руках. Начинается стычка."},"E118.3":{"s":"Вы оставляете спор двум орочьим семьям. До рассвета остаётся совсем немного, а солдат по-прежнему лежит у огня."},"E118.4":{"s":"Солдат, собрав последние силы, выбирает службу Королю вместо неопределённого плена. Семьи позволяют ему уйти с отрядом.","f":"Солдат не может дать осмысленный ответ, и семьи отказываются заключать соглашение за него. Нового бойца отряд не получает.","v":{"rs":"Солдат выбирает службу, но принять его в отряд невозможно. Он благодарит за предложенный выбор золотом."}},"E118.5":{"s":"После жёсткого требования семьи соглашаются отпустить пленника за денежную компенсацию. Отряд получает золото, хотя орки провожают его неприязненно.","f":"Орки отвергают притязание на пленника как на вещь и зовут бойцов обоих кланов. Начинается битва."},"E119.1":{"s":"Король подписывает перенос рейса к ближайшему кладбищу, и Рем наконец убирает часы. Из багажа давно исчезнувших пассажиров он выделяет отряду припасы."},"E119.2":{"s":"Вы закрываете рейс королевской подписью, и пассажиры молча покидают дилижанс. Рем передаёт вам старую кассу с золотом.","f":"Рем объявляет закрытие рейса нарушением обязательств перед пассажирами. Из кареты выходят вооружённые мертвецы — начинается стычка."},"E119.3":{"s":"Рем достаёт из ящика ведомость и выплачивает накопившийся дорожный налог золотом. Его часы наконец перестают тикать.","f":"Требование налога за сто сорок два года возмущает всех двенадцать пассажиров. Они поднимаются из кареты с оружием — начинается битва."},"E119.4":{"s":"Вы отказываетесь подписывать чужой документ неизвестными чернилами. Рем тяжело вздыхает, сверяет часы и продолжает ждать следующего монарха."},"E120.1":{"s":"Вы не трогаете старую обувь и позволяете семье Агны спокойно досидеть до рассвета. Хозяйка даёт в дорогу еду в благодарность."},"E120.2":{"s":"Агна объясняет, кому была приготовлена четвёртая миска, и в знак доверия достаёт старый кошель с золотом. Мертвецы не вмешиваются в разговор.","f":"Агна принимает вопрос за попытку нарушить семейный обычай, и мертвецы поднимаются из-за стола. Начинается стычка."},"E120.3":{"s":"{{heroName}} замечает, что четвёртая миска предназначена не мертвецу, а гостю, которого Агна ждала все эти годы. За разгаданную тайну она отдаёт золото и припасы.","f":"{{heroName}} не может связать пустой стул с семейной историей Агны. Хозяйка просит не тревожить умерших расспросами."},"E120.4":{"s":"Вы выводите мертвецов из дома и находите в их оставленном снаряжении старые монеты. Агна смотрит на пустые стулья, не поблагодарив вас.","f":"Муж и сыновья Агны не позволяют выгнать себя из дома, а снаружи собираются другие мертвецы. Начинается битва."},"E120.5":{"s":"Вы уходите прежде, чем к дому подходят ночные гости. У порога остаются три пары старых сапог и одна свободная миска."},"E121.1":{"s":"Король оплачивает мелкие недоимки из своей казны, и Ротмар вычёркивает сразу несколько строк. Духи освобождают место в очереди, но мост герцога всё ещё числится долгом."},"E121.2":{"s":"Вы собираете с должников оставшиеся монеты и закрываете часть записей в книгах Ротмара. Золото переходит отряду.","f":"Один из призраков объявляет взыскание незаконным, и остальные должники поднимают возмущение. Кладбищенская очередь превращается в стычку."},"E121.3":{"s":"{{heroName}} находит в книгах встречные долги и сводит баланс без воображаемого моста. Ротмар благодарит золотом и припасами, впервые отложив перо.","f":"{{heroName}} обнаруживает ещё одну незакрытую строку: семь кур герцога уже списаны, но мост всё ещё должен существовать. Ротмар продолжает считать."},"E121.4":{"s":"Вы выкупаете долговую книгу за золото, и Ротмар торжественно оформляет передачу требований. Покойники смотрят на нового кредитора с явным неодобрением."},"E121.5":{"s":"Вы оставляете лича за его столом среди нетерпеливых духов. Вслед он просит передать герцогу, что мост всё-таки нужен."},"E122.1":{"s":"Ард произносит долгожданную клятву, а Селена отвечает так тихо, что слышит только он. Призрачные гости собирают для старика золотой свадебный дар.","f":"Ард не может закончить обещание и отступает от алтаря. Селена не удерживает его, но свадебная процессия так и не расходится."},"E122.2":{"s":"Селена признаёт, что ожидание не должно отнимать у Арда остаток жизни. Призраки освобождают дорогу, а благодарные путники делятся припасами.","f":"Призрачные родственники считают ваши слова попыткой сорвать свадьбу и встают между вами и Ардом. Начинается стычка."},"E122.3":{"s":"{{heroName}} завершает свадебный обряд как память о данном обещании, не требуя от Арда переходить к мёртвым. Старик отдаёт золото, а гости оставляют припасы.","f":"{{heroName}} не находит безопасной формулы для клятвы между живым и умершей. Обряд остаётся незавершённым."},"E122.4":{"s":"Вы выводите Арда из часовни прежде, чем призрачная процессия успевает сомкнуть круг. Он идёт сам, хотя всё время оглядывается на Селену.","f":"Призрачные гости встают перед выходом, не позволяя увести жениха против его воли. Начинается битва."},"E122.5":{"s":"Вы оставляете Арда сидеть напротив Селены, не решая за него. Призрачная процессия терпеливо ждёт первого слова жениха."},"E123.1":{"s":"Вы подсказываете Фелену новую последнюю песню, и кладбищенская публика наконец требует занавеса. Из благодарственных подношений артист отдаёт золото.","f":"Покойники недовольны новой балладой и требуют ещё один круг выступлений. Чтобы дождаться перерыва, отряд тратит припасы."},"E123.2":{"s":"Вы платите Фелену и уводите его с импровизированной сцены под возмущённый свист могил. Музыкант соглашается вступить в отряд.","f":"Стоит артисту сойти с места, как из могил выходят вооружённые слушатели. Начинается стычка.","v":{"rs":"Фелен готов уйти с вами, но нового бойца принять не удаётся. За помощь он передаёт золото, оставаясь у кладбищенской сцены."}},"E123.3":{"s":"Вы берёте у Фелена лютню и заканчиваете выступление такой песней, что даже крышки гробов умолкают. Из оставленных монет отряду достаётся золото.","f":"Публика отвечает на фальшивую ноту градом костей, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Кладбищенская публика осыпает сцену костями, но никто из допустимых бойцов не получает тяжёлого ранения. Концерт продолжается без награды."}},"E123.4":{"s":"Вы разбираете сцену до последней доски, лишив покойников повода требовать ещё песен. Фелен наконец может выйти за ворота.","f":"Кладбищенская публика восстаёт против отмены представления и выходит из могил с оружием. Начинается битва."},"E123.5":{"s":"Вы дослушиваете балладу и уходите во время довольных аплодисментов. Фелен незаметно передаёт вам дорожную еду, пока зрители заняты."},"E124.1":{"s":"Вы принимаете позицию у моста, а беженцы благодарят золотом и припасами ещё до сражения. Из ущелья уже приближаются твари — начинается битва."},"E124.2":{"s":"Пока скелет удерживает мост, вы выводите караван скрытой тропой. Беженцы делятся спасёнными припасами.","f":"Существа из ущелья замечают движение каравана и отрезают отряду путь к отступлению. Начинается стычка."},"E124.3":{"s":"Вы предлагаете скелету сменить службу у моста на место рядом с Королём. Страж принимает новое назначение и вступает в отряд.","f":"Страж отвечает, что не оставит пост, пока живые не уйдут в безопасность. Нового союзника отряд не получает.","v":{"rs":"Страж принимает предложение сменить пост, но включить нового бойца в отряд невозможно. Беженцы оставляют вам золото в благодарность за попытку помочь."}},"E124.4":{"s":"Вы освобождаете старого стража от бесконечной караульной клятвы. В оставленных доспехах находят золото.","f":"Попытка снять клятву открывает переправу тварям из ущелья. Отряду приходится вступить в битву."},"E124.5":{"s":"Вы выбираете обход перевала и тратите лишние припасы на длинный путь. Скелет остаётся на мосту перед караваном."},"E125.1":{"s":"Нерисс принимает восемь монет и отводит край паутины, словно занавес. Паук молча проверяет, не остался ли кто должен."},"E125.2":{"s":"Вы находите ошибку в подсчёте Нерисс, и она вынужденно отдаёт несколько монет в вашу пользу. Паук стучит лапой по табличке, требуя исправить цену.","f":"Нерисс записывает ваши возражения как платную жалобу и взыскивает дополнительное золото. Паук одобрительно шевелит лапой."},"E125.3":{"s":"{{heroName}} проходит по скальному уступу выше сети и показывает безопасный обход остальным. В найденном по пути схроне остаются припасы.","f":"Под ногами разведчика обрывается узкий выступ, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Скальный уступ осыпается, но никто из допустимых бойцов не получает тяжёлого ранения. Обход найти не удаётся."}},"E125.4":{"s":"Вы разрубаете сеть, и среди застрявших в нитях вещей находите золото. Нерисс не успевает назначить новую пошлину.","f":"Паук принимает повреждение полотна за неоплаченную услугу и выпускает вооружённых защитников. Начинается стычка."},"E125.5":{"s":"Вы разворачиваете отряд перед паутиной и уходите той же дорогой. Нерисс записывает в книгу ещё одного несостоявшегося плательщика."},"E126.1":{"s":"Вы скрепляете отказ Вессары от ложного заказа своей подписью. Убийца передаёт золото за свидетельство, а Олм облегчённо выдыхает."},"E126.2":{"s":"Вы находите в приложении к контракту имя того, кто выдал заказ, и несоответствие печатей. Вессара платит золотом за обнаруженную подделку.","f":"В приложении оказываются только одинаковые юридические формулы без новых имён. Установить заказчика не удаётся."},"E126.3":{"s":"{{heroName}} спрашивает Олма о кольце и находит противоречие между его ответами и текстом заказа. Вессара отдаёт золото за помощь в разоблачении.","f":"Олм отвечает осторожно и затягивает спор до темноты; на ожидание уходят припасы. {{heroName}} не находит достаточных доказательств."},"E126.4":{"s":"Вы передаёте связанного Олма Вессаре без дальнейшего допроса. Она расплачивается золотом, не обещая, что он выйдет из-под акведука свободным."},"E126.5":{"s":"Вы обезоруживаете Вессару и удерживаете Олма для суда. При них находят золото, переданное отряду как обеспечение разбирательства.","f":"Вессара выхватывает спрятанный кинжал, а Олм срывает путы. Попытка ареста превращается в стычку."},"E127.1":{"s":"Саэр проводит отряд через подземный тракт, а его тень ни разу не отстаёт настолько, чтобы перекрыть путь. На выходе он делится припасами.","f":"В тесном проходе чужая тень хватает {{affectedHeroName}} за ноги, оставляя тяжёлое ранение.","v":{"nf":"Тень бросается на отряд, но никто из допустимых бойцов не получает тяжёлого ранения. Проход приходится покинуть без платы."}},"E127.2":{"s":"Вы направляете яркий свет под ноги Саэру, и его тень отлипает от камня. Проводник благодарит вас золотом.","f":"Тень не исчезает от света, а поднимается с пола отдельной вооружённой фигурой. Начинается стычка."},"E127.3":{"s":"{{heroName}} определяет, что тень привязана к старой дорожной метке, а не к Саэру. За разъяснение проводник отдаёт припасы.","f":"{{heroName}} не находит надёжного следа магии, зато попытки проверить тень расходуют припасы. Саэр остаётся с прежним вопросом."},"E127.4":{"s":"Вы обращаетесь к тени как к отдельному существу, и она отвечает условием: золото за право оставить Саэра в покое. Договор приносит отряду плату.","f":"Тень отказывается говорить с людьми, отделяется от Саэра и зовёт существ подземного тракта. Начинается битва."},"E127.5":{"s":"Вы отказываетесь от проводника, чья тень ходит по своим правилам. Саэр молча уходит в подземный тракт, а тень задерживается на один шаг."},"E128.1":{"s":"Вы признаёте выигрыш Ситы и расходуете припасы, помогая поднять груз по каменной стене. Кель благодарит золотом, а паучиха победно постукивает лапами."},"E128.2":{"s":"Вы заменяете подпиленные кости честными, и новый бросок решает спор без обмана. Кель платит золото за восстановленные правила.","f":"Сита отказывается признавать переигровку, пока Кель не выплатит ей неустойку. За попытку примирить спорщиков золото удерживают с отряда."},"E128.3":{"s":"{{heroName}} проводит честное состязание на доступном маршруте, и Кель с Ситой признают новый результат. За судейство отряду достаётся золото.","f":"На крутом спуске {{affectedHeroName}} получает тяжёлое ранение, когда Сита резко меняет направление.","v":{"nf":"На опасном повороте гонка останавливается, но никто из допустимых бойцов не получает тяжёлого ранения. Судейской награды нет."}},"E128.4":{"s":"Вы отдаёте золото за подпиленные кости и прячете их как доказательство обмана. Сита провожает покупку тремя недовольными ударами лапы."},"E128.5":{"s":"Вы оставляете Келя и Ситу выяснять условия старого пари. Паучиха уже переносит седло на вертикальную стену."},"E129.1":{"s":"Старший наследник касается обсидиана и видит последнее сильное воспоминание, оставленное князем. Семья выдаёт отряду золото за проведение обряда.","f":"Плита показывает лишь смутный образ без лица, а прикосновение стирает прежний след. Наследники снова начинают спор."},"E129.2":{"s":"Король касается обсидиана, и на поверхности проступает воспоминание о последнем дне князя. Семья расплачивается золотом за увиденное.","f":"Чужое воспоминание обжигает Короля изнутри, оставляя тяжёлое ранение. Образ князя гаснет.","v":{"nf":"Обсидиан отвечает болезненным всплеском, но Король не получает тяжёлого ранения. Воспоминание так и не удаётся прочесть."}},"E129.3":{"s":"{{heroName}} сопоставляет ответы четырёх наследников и находит того, кто скрывает свою встречу с князем. За выводы семья платит золотом, не касаясь плиты.","f":"{{heroName}} обнаруживает слишком много противоречий, чтобы назвать одного виновного. Единственную попытку решают пока сохранить."},"E129.4":{"s":"Вы запечатываете обсидиан, не позволяя ни одному наследнику стирать чужую память. Эшра благодарит отряд оставленными дорожными припасами."},"E129.5":{"s":"Вы продаёте право коснуться плиты самому щедрому наследнику и получаете золото. Остальные вынуждены принять сделку.","f":"Соперники обвиняют победителя торгов в подкупе и обнажают оружие прямо у плиты. Начинается битва."},"E130.1":{"s":"Вы оплачиваете Лиан дорогу к лекарям, и она впервые берёт с полки не фамильный капюшон, а собственную сумку. Мерет молча наливает ей чай."},"E130.2":{"s":"Вы поддерживаете требование Мерета о наследовании ремесла. Палач благодарит золотом, а Лиан ставит недопитую чашку на стол."},"E130.3":{"s":"Вы предлагаете Лиан учиться врачеванию, не разрывая полностью семейную традицию знания человеческого тела. Мерет расплачивается золотом и добавляет припасы к дороге.","f":"Лиан отвечает, что хочет лечить живых, а не искать красивое название старой профессии. Разговор заканчивается без согласия."},"E130.4":{"s":"Лиан собирает перевязочный набор и решает начать практику в вашем походе. Мерет нехотя благословляет её у двери.","f":"Мерет не разрешает дочери уходить в незнакомый отряд, и Лиан остаётся дома. Нового спутника вы не получаете.","v":{"rs":"Лиан готова пойти с вами, но принять нового бойца не удаётся. Она вручает отряду золото и остаётся готовиться к обучению."}},"E130.5":{"s":"Вы допиваете чай и не вмешиваетесь в спор Мерета с Лиан. Перед уходом девушка незаметно кладёт вам дорожные припасы."},"E131.1":{"s":"Лестница скрипит, но выдерживает; вскоре новая шестерня возвращает подъёмник к жизни. Дорн отсчитывает награду, пока из клетки радостно кричат: «Пиво спасено!»","f":"На обратном пути прогнившие ступени срываются с креплений. {{affectedHeroName}} успевает предупредить остальных, но получает тяжёлое ранение.","v":{"nf":"Ступени аварийной лестницы осыпаются, но никто из доступных бойцов не получает тяжёлого ранения. Шестерню приходится оставить на нижнем этаже."}},"E131.2":{"s":"Отряд тянет цепи до онемения пальцев, и клетка наконец поднимается к краю шахты. Спасённые шахтёры делятся запасами, хотя с бочонком расставаться отказываются.","f":"Цепь рывком выскальзывает из рук, а клетка остаётся висеть над пустотой. На бесплодные попытки уходит ещё часть припасов."},"E131.3":{"s":"{{heroName}} связывает вагонетки цепями и собирает механизм, над которым Дорн сперва только смеялся. Когда клетка выбирается наверх, шахтёры платят золотом и делятся провизией.","f":"Цепь натягивается, вагонетки скрежещут — и вся передача рассыпается на глазах у Дорна. {{heroName}} сердито просит больше не называть это подъёмником."},"E131.4":{"s":"Клетка срывается вниз, но нижний тормоз с грохотом ловит её за миг до удара. Шахтёры выбираются на свет и щедро платят за спасение.","f":"Трос лопается раньше условного сигнала, и тормоз не справляется. Крики из шахты заставляют отряд обнажить оружие: впереди битва."},"E131.5":{"s":"Вы оставляете Дорна и его товарищей разбираться с поломкой. Из глубины шахты вам вслед кричат, что бочонок пока ещё полон."},"E132.1":{"s":"Брун и Келд спорят над каждой работой, пока нотариус Мара не объявляет результат состязания. Победитель вручает вам обещанную плату, а проигравший уже требует реванша.","f":"Братья ссорятся ещё до первого удара молота; состязание приходится свернуть. Пока вы разводите их по разным углам, расходуется часть провизии."},"E132.2":{"s":"В кузне устанавливают вторую наковальню, и братья впервые за весь день замолкают. За мирное решение они выдают вам припасы.","f":"Первый же спор о том, кому достанется горн, заканчивается дракой. Вместо делёжки наследства вас ждёт стычка."},"E132.3":{"s":"{{heroName}} обращает внимание братьев на слова покойного отца, а не на спорную кузню. Мара признаёт решение справедливым и выдаёт награду.","f":"{{heroName}} находит новую зацепку, но братья тут же истолковывают её каждый в свою пользу. Завещание остаётся предметом спора."},"E132.4":{"s":"Вы выкупаете у братьев кузню, заплатив положенную сумму. Нотариус Мара торопливо заверяет договор, пока Брун и Келд не передумали."},"E132.5":{"s":"Вы отказываетесь толковать загадочные слова покойного дварфа. Мара вздыхает, а братья тут же требуют хотя бы бросить монету."},"E133.1":{"s":"«Малютка» грохочет так, что у расчёта звенит в ушах; снежная стена наконец уходит в ущелье. Благодарные дварфы снабжают вас припасами.","f":"Выстрел срывает со склона лишь жалкую горсть снега. Фрида задумчиво просит четвёртый вариант расчётов."},"E133.2":{"s":"Вместо рискованного выстрела отряд берётся за лопаты и к вечеру открывает проход. Дварфы платят золотом за тяжёлую, но надёжную работу."},"E133.3":{"s":"{{heroName}} находит ошибку в расчётах и велит переставить заряды. Лавина уходит туда, куда нужно, а расчёт «Малютки» благодарит вас монетами и запасами.","f":"Даже исправленные расчёты не спасают положение: снег остаётся на дороге. Фрида впервые за день не спорит с {{heroName}}."},"E133.4":{"s":"Вы оплачиваете ещё один снаряд для «Малютки». Фрида торжественно обещает, что на этот раз расчёты непременно совпадут."},"E133.5":{"s":"Отряд уходит искать другой перевал, оставляя Фриду с пушкой размером в дом. Долгий обход съедает часть припасов."},"E134.1":{"s":"Королевский указ зачитывают перед бочкой с такой торжественностью, что руна наконец исчезает. Хальда торжествующе раздаёт содержимое, а отряду достаются припасы.","f":"Бочка выслушивает указ и выводит на крышке новую надпись: «НЕ УБЕДИЛИ». Хальда заявляет, что теперь ненавидит государственные праздники."},"E134.2":{"s":"После третьего удара крышка всё-таки сдаётся, и пивоварня взрывается торжествующим рёвом. Хальда наливает всем и отдаёт часть запасов в дорогу.","f":"Молот ломается о крышку, а руна выводит: «ПОПЫТКА ЗАСЧИТАНА, ВЕЛИЧИЕ — НЕТ». Хальда просит вас больше не поощрять бочку."},"E134.3":{"s":"{{heroName}} расшифровывает старую руну и произносит условие, о котором дед Хальды предпочёл умолчать. Бочка открывается, а пивоварня благодарит отряд золотом и припасами.","f":"{{heroName}} читает руну, но та тут же перестраивается и требует подвига ещё более великого. Хальда в отчаянии зовёт следующего толкователя."},"E134.4":{"s":"Коллекционер покупает неоткрытую бочку исключительно ради надписи «НЕ ДОСТАТОЧНО ВЕЛИКО». Хальда делится с вами золотом за удачный совет.","f":"Коллекционер требует доказательств, что пиво вообще существует, а бочка отказывается их предоставить. Сделка срывается."},"E134.5":{"s":"Вы оставляете бочку ждать по-настоящему великого случая; Хальда выдаёт вам провизию на дорогу. На крышке появляется слово «ТЕРПЕНИЕ»."},"E135.1":{"s":"Тоб натягивает мягкое заграждение, и Ринна наконец останавливается, не разбив машину вдребезги. Механик платит вам золотом.","f":"Ринна пролетает сквозь баррикаду, разбросав мешки по дороге. Приходится расходовать новые припасы на уборку обломков."},"E135.2":{"s":"Вы цепляетесь за мотоцикл на полном ходу и дотягиваетесь до аварийного рычага. Ринна останавливается, а механик Тоб вручает награду дрожащими руками.","f":"Колёса уходят из-под ног раньше, чем удаётся схватиться за седло. {{affectedHeroName}} остаётся на дороге с тяжёлым ранением.","v":{"nf":"Мотоцикл ускользает от перехватчика, но никто из доступных бойцов не получает тяжёлого ранения. Ринна продолжает опасную поездку."}},"E135.3":{"s":"{{heroName}} ведёт Ринну вверх по длинному склону, пока руна движения не теряет силу. Тоб вручает отряду золото и припасы.","f":"Руна лишь разгорается от каждого нового подъёма, и Ринна снова исчезает за горизонтом. {{heroName}} признаёт, что машина оказалась упрямее."},"E135.4":{"s":"Тоб попадает в источник питания, и мотоцикл с последним рыком замирает у края дороги. Механик платит за спасение золотом.","f":"Выстрел повреждает защитную руну, и из разорванного контура выходят сторожевые автоматы. Начинается стычка."},"E135.5":{"s":"Вы отступаете на обочину, когда Ринна проносится мимо в четвёртый раз. Тоб кричит вслед, что «система теоретически надёжна»."},"E136.1":{"s":"Окко отключает блокировку, и «Синица» взлетает выше деревьев, дрожа от страха и ветра. Пилот благодарит вас золотом.","f":"«Синица» начинает взлёт, затем резко садится и требует проверить двигатель; на повторные испытания уходят припасы."},"E136.2":{"s":"Окко соглашается снять крылья и оставить «Синицу» ездить по земле. За необычный, но рабочий совет он платит золотом.","f":"«Синица» отказывается быть телегой с винтом, а Окко снова берётся за лётную инструкцию. Покупателя не находится."},"E136.3":{"s":"{{heroName}} предлагает серию коротких подскоков, и «Синица» постепенно привыкает не касаться земли. Окко радуется так громко, что платит и золотом, и припасами.","f":"Даже на ладонь над травой «Синица» глушит двигатель и садится обратно. {{heroName}} решает не мучить испуганную машину."},"E136.4":{"s":"Окко садится рядом с вами за штурвал, и «Синица» наконец перелетает луг, не опустившись обратно. Пилот платит золотом за лучший полёт в своей жизни.","f":"На первом же подъёме «Синица» резко останавливает винт; {{affectedHeroName}} тяжело ранен при жёсткой посадке.","v":{"nf":"«Синица» срывает первый подъём, но никто из доступных бойцов не получает тяжёлого ранения. Окко решает не повторять попытку."}},"E136.5":{"s":"Вы оставляете Окко и «Синицу» разбираться с боязнью высоты без королевского участия. На лугу снова слышно осторожное жужжание винта."},"E137.1":{"s":"Фазз выдаёт оплаченные припасы и указывает на подпись под сорок седьмой страницей. На этот раз договор действительно исполнен.","f":"На странице сорок шестой обнаруживается пункт о плате за хранение припасов. После сделки их остаётся меньше, чем рассчитывал отряд."},"E137.2":{"s":"Демон радостно записывает новый мост в свою честь и выкладывает золото за право владеть названием. О том, где находится сам мост, он не спрашивает.","f":"Фазз находит в договоре условие о проверке существования моста и взыскивает неустойку. Часть казны уходит на юридическую неожиданность."},"E137.3":{"s":"{{heroName}} находит в приложении право покупателя расторгнуть договор на любой сорок восьмой странице. Фазз платит золотом, чтобы спор не дошёл до суда.","f":"{{heroName}} проверяет каждую строку, но Фазз предусмотрел даже право на проверку права проверки. Демон вежливо предлагает новый контракт."},"E137.4":{"s":"Король подписывает исполинский договор, и Фазз отсчитывает внушительную сумму золотом. Последние страницы остаются подозрительно тёплыми.","f":"Договор стягивает подпись в чёрную печать, и {{affectedHeroName}} получает тяжёлое ранение. Фазз извиняется за «стандартное условие».","v":{"nf":"Чёрная печать договора вспыхивает под королевской подписью, но никто из доступных бойцов не получает тяжёлого ранения. Фазз прячет последние страницы."}},"E137.5":{"s":"Вы уходите, не пожелав читать договор размером с дверь. Демон Фазз вслед предлагает бесплатную консультацию на сорока семи листах."},"E138.1":{"s":"Три головы одновременно бросаются за палкой, освобождая дорогу. Егерь Кхар смотрит на вас с искренним ужасом, но проход остаётся открыт.","f":"Пёс возвращает палку раньше, чем вы успеваете пройти, и снова переграждает путь. Кхар кричит, что предупреждал."},"E138.2":{"s":"Кхар принимает золото и удерживает пса за все три ошейника. Отряд проходит мимо, пока хвост чудовища сбивает очередной дорожный знак."},"E138.3":{"s":"{{heroName}} увлекает пса игрой к безопасной поляне, и тот забывает про дорогу. Кхар выдаёт золото и немного припасов.","f":"Пёс хватает палку вместе с перчаткой, и {{affectedHeroName}} получает тяжёлое ранение. Кхар бросается разнимать собственного любимца.","v":{"nf":"Адский пёс хватает палку вместе с перчаткой, но никто из доступных бойцов не получает тяжёлого ранения. Кхар прекращает игру."}},"E138.4":{"s":"Кхар швыряет вам золото, обещанное за устранение помехи, но пёс уже разинул все три пасти. Начинается битва."},"E138.5":{"s":"Отряд карабкается по осыпи выше обугленной дороги, теряя часть припасов. Внизу всё ещё слышится радостный лай сразу трёх голов."},"E139.1":{"s":"Ишра взвешивает чёрную монету на когте и платит золото за редкий предмет. Мира отворачивается прежде, чем он успевает назвать её цену."},"E139.2":{"s":"Монета раскалывается на две чёрные половины, и Мира впервые спокойно выдыхает. За помощь она делится припасами.","f":"При первом ударе монета зовёт демона Ишру к оружию; тот не желает терять свою находку. Разгорается стычка."},"E139.3":{"s":"{{heroName}} снимает проклятие, не уничтожая память о совершённом поступке. Мира благодарит вас золотом и припасами, впервые не пряча взгляда.","f":"{{heroName}} замечает, что монета лишь перенаправляет проклятие при попытке очистить её. Ритуал прекращают, не рискуя чужой памятью."},"E139.4":{"s":"Монета ложится вам на ладонь ледяным пятном; вместе с ней вы получаете золото, но чужую вину уже не стряхнуть одним движением.","f":"Монета обжигает того, кто решился взять её, и {{affectedHeroName}} получает тяжёлое ранение. Ишра молча убирает руки за спину.","v":{"nf":"Чужая монета обжигает взявшего её, но никто из доступных бойцов не получает тяжёлого ранения. Ишра просит оставить находку на дороге."}},"E139.5":{"s":"Вы уходите от костра, где Ишра и Мира всё ещё смотрят на чёрную монету. Никто из них не пытается вас задержать."},"E140.1":{"s":"Оба живых посетителя находят в списках собственные даты рождения и доказывают, что ещё не умерли. Ульф выдаёт вам припасы в качестве «служебного возмещения».","f":"Регистратор требует справку о том, что живые действительно живы, выданную после смерти. Чтобы вытащить людей из очереди, приходится потратить золото."},"E140.2":{"s":"Ульф берёт плату за срочное обслуживание и неожиданно возвращает вам часть денег по официальной компенсации. Очередь движется на два шага."},"E140.3":{"s":"Королевский приказ заставляет Ульфа закрыть незаконный портал и выдать штраф золотом. Призраки требуют подписать решение задним числом.","f":"Ульф вызывает стражу загробного архива, чтобы защитить действующую очередь. Начинается стычка."},"E140.4":{"s":"Вы доходите до окошка и неожиданно получаете золото как «компенсацию за ошибочную регистрацию». Ульф тут же закрывает приём на обед.","f":"Ульф выдаёт талон с номером, который в этой очереди ещё никто не видел. Отряд уходит ни с чем."},"E140.5":{"s":"Вы обходите очередь так широко, что последний призрак даже не замечает вас. Ульф вслед объявляет новую графу: «Покинул без подачи заявления»."},"E141.1":{"s":"Царр вручает бесплатную ампулу и вписывает Короля в журнал покупателей. За семь минут её действия никто пока не поручается.","f":"Стеклянная ампула трескается ещё у прилавка, и часть походных припасов уходит на уборку едкой смеси. Царр напоминает, что реклама возврату не подлежит."},"E141.2":{"s":"Вы отсчитываете тридцать золотых, а Царр укладывает в футляр ещё две ампулы. Он отдельно предупреждает, что минуты нельзя складывать друг с другом."},"E141.3":{"s":"{{heroName}} замечает в журнале странное условие: семь минут не прибавляют жизни, а только откладывают последствия. Царр платит припасами за точную проверку.","f":"{{heroName}} не может разобрать состав без вскрытия ампулы, а Царр отказывается пожертвовать товаром. Проверка остаётся незавершённой."},"E141.4":{"s":"Испытуемый выпивает содержимое и проходит проверку без заметного вреда. Царр выплачивает обещанное золото за демонстрацию.","f":"Когда действие смеси обрывается, {{affectedHeroName}} получает тяжёлое ранение. Царр торопливо захлопывает журнал отзывов.","v":{"nf":"Ампула даёт опасную реакцию, но никто из допустимых бойцов не получает тяжёлого ранения. Царр не выплачивает награды."}},"E141.5":{"s":"Вы разбиваете ампулы прежде, чем Царр успевает их спрятать. Из его прилавка удаётся забрать золото в счёт опасного товара.","f":"Царр зовёт вооружённых покупателей, которым не нравится уничтожение их будущего бессмертия. Начинается битва."},"E142.1":{"s":"Король расписывается на заявлении, и зеркало впервые замолкает. Гриск решает не возвращаться в легион и вступает в отряд.","f":"Из зеркала выпрыгивают исполнители приказа начальницы и требуют вернуть Гриска в строй. Начинается стычка.","v":{"rs":"Заявление подписано, но Гриск не может присоединиться к отряду. Он благодарит за увольнение золотом и уходит своим путём."}},"E142.2":{"s":"Гриск выкладывает золото за королевскую подпись быстрее, чем начальница успевает возразить из зеркала. Свидетельство оформлено.","f":"Начальница из зеркала заявляет, что плата свидетелю аннулирует независимость подписи. Гриск остаётся с неподписанным заявлением."},"E142.3":{"s":"Вы советуете Гриску просто не являться к начальнице, и он впервые за век улыбается. В благодарность он оставляет припасы.","f":"Гриск показывает пункт договора о наказании за прогул и снова берётся за заявление. Совета оказалось недостаточно."},"E142.4":{"s":"Вы отказываете Гриску и возвращаете начальнице её зеркало через посыльного. В ответ приходит золото за соблюдение легионного порядка."},"E142.5":{"s":"Зеркало раскалывается, и голос начальницы исчезает вместе с печатью подчинения. Гриск признаёт себя свободным и присоединяется к отряду.","f":"Из осколков зеркала вырывается ответный удар, и {{affectedHeroName}} получает тяжёлое ранение. Гриск по-прежнему связан службой.","v":{"rs":"Связь с легионом разорвана, но Гриск не может вступить в отряд. За освобождение он передаёт золото.","nf":"Осколки зеркала разлетаются в стороны, но никто из допустимых бойцов не получает тяжёлого ранения. Заявление Гриска остаётся в силе старого договора."}},"E143.1":{"s":"Вы передаёте жителям две доли провизии и помогаете поднять обгоревшие балки. Эйрен остаётся рядом, не снимая грязных перчаток."},"E143.2":{"s":"Вы убеждаете Эйрена продолжить преследование, обещая передать помощь деревне. Ангел оставляет золото для погорельцев и отряда.","f":"Эйрен отказывается уходить и просит не превращать чужую беду в спор о приказах. На помощь жителям уходят припасы."},"E143.3":{"s":"Вы посылаете разведчиков по следу демонов и возвращаете найденные у врагов ценности. Золото достаётся отряду, пока Эйрен помогает деревне.","f":"Разведка сталкивается с вооружённым демоническим дозором прежде, чем успевает вернуться. Начинается стычка."},"E143.4":{"s":"Эйрен принимает предложение Короля, рассчитывая найти поддержку для пострадавшей деревни. Ангел вступает в отряд.","f":"Эйрен благодарит за приглашение, но не может оставить погорельцев даже на время. Он продолжает разбирать завалы.","v":{"rs":"Эйрен готов присоединиться, но взять нового бойца невозможно. Он передаёт золото на дальнейшую помощь и остаётся у деревни."}},"E143.5":{"s":"Вы оставляете Эйрена среди обугленных стен. Ангел подхватывает очередную балку вместе с теми, кого недавно защищал."},"E144.1":{"s":"Вы помогаете Саэлю снять сияющие кольца с прилавка, и торговля прекращается. Ангел выплачивает золото за содействие.","f":"Пел объявляет конфискацию грабежом и зовёт вооружённых помощников. Начинается стычка."},"E144.2":{"s":"Вы отсчитываете плату и получаете одно сияющее кольцо с условием «возврат по требованию небес». Пел поспешно прячет выручку.","f":"До завершения покупки Саэль требует вернуть кольцо и останавливает сделку. Золото уже ушло Пелу и не возвращается."},"E144.3":{"s":"{{heroName}} закрепляет кольца у земли, пока Саэль снимает их с прилавка. За помощь ангел выдаёт золото и припасы.","f":"{{heroName}} обнаруживает, что кольца нельзя удержать без риска для торговца. Конфискацию приходится остановить."},"E144.4":{"s":"Вы признаёте довод Пела об аренде, и торговец платит за поддержку своего дела. Саэль требует показать хоть один подписанный ангелом договор.","f":"Пел не может предъявить договор аренды и замолкает под взглядом Саэля. Золота за поддержку вы не получаете."},"E144.5":{"s":"Вы отходите от прилавка до того, как Пела поднимает над землёй окончательно. Саэль всё ещё спорит с ним о праве собственности."},"E145.1":{"s":"Вы задаёте вопросы по одному и обнаруживаете, чьё молчание заставляет колокол звенеть. Офира оплачивает золотом разгаданную загадку.","f":"Паломники отвечают без противоречий, но серебряный колокол продолжает звенеть на неозвученные вопросы. Разбирательство не продвигается."},"E145.2":{"s":"Паломники записывают ответы, и колокол впервые не прерывает их. По записям Офира находит причину тревоги и выдаёт золото.","f":"Колокол звенит даже над пустыми листами; на долгие поиски объяснения уходят припасы. Записки ничего не проясняют."},"E145.3":{"s":"{{heroName}} обнаруживает, что ритуал реагирует на намерение скрыть правду, ещё до произнесения слов. Офира благодарит за исправленное толкование золотом.","f":"{{heroName}} проверяет крепление и надписи, но сам ритуал не удаётся понять. Колокол продолжает звонить без ответа."},"E145.4":{"s":"Вы снимаете серебряный колокол с крепления, и его звон обрывается. Офира смотрит на пустую перекладину, не решаясь вас остановить.","f":"Попытка снять святыню вызывает небесную стражу. Из боковых проходов часовни выходят вооружённые защитники — начинается битва."},"E145.5":{"s":"Вы оставляете Офиру и паломников наедине с колоколом. Серебряный звон провожает отряд до самой дороги."},"E146.1":{"s":"Вы выкупаете заложенное крыло, и Вельт снимает его с учёта. Нира бережно принимает перья обратно, пока ростовщик прячет золото."},"E146.2":{"s":"Вы требуете показать разрешение на торговлю ангельскими крыльями, и Вельт уступает, выплатив золото за отказ от претензий.","f":"Вельт предъявляет подписанный договор и выставляет счёт за ложное обвинение. Отряду приходится расстаться с золотом."},"E146.3":{"s":"{{heroName}} находит в договоре нарушение: крыло нельзя отчуждать как целую вещь вместе с должником. Вельт выплачивает золото за урегулирование спора.","f":"{{heroName}} не находит основания отменить вчерашний срок, а Нира остаётся перед решёткой ломбарда. Спор продолжается."},"E146.4":{"s":"Вы уплачиваете часть долга, и Нира соглашается служить в отряде, пока её обязательство не будет погашено.","f":"Нира не принимает службу как плату за свободу собственного крыла. Внесённое золото остаётся у Вельта, нового союзника нет.","v":{"rs":"Нира принимает договор, но места для нового бойца нет. Она передаёт золото вместо службы, а уплаченная часть долга не возвращается."}},"E146.5":{"s":"Вы оставляете Ниру у ломбарда, а Вельта — за расчётами с будущим покупателем крыла. Сделку никто не оспаривает."},"E147.1":{"s":"Вы проходите милю задом наперёд и замечаете старую тропу с забытым кошелём и припасами. Амарон благодарит за компанию.","f":"Следуя совету Амарона, отряд сбивается с дороги и расходует припасы на возвращение. Ангел просит смотреть под ноги чаще."},"E147.2":{"s":"Амарон благословляет путь отряда и дарит дорожные припасы вместо совместной прогулки. Сам он продолжает пятиться к горизонту."},"E147.3":{"s":"Вы сопровождаете Амарона обычным шагом, предупреждая о камнях и поворотах. Он благодарит золотом за заботу.","f":"Амарон отказывается от сопровождения, которое лишает его испытание смысла. Вы расходитесь без награды."},"E147.4":{"s":"Амарон соглашается, что уже научился видеть дорогу позади, и впервые за сорок дней поворачивается лицом вперёд.","f":"Амарон отвечает, что никто другой не вправе назначать конец его уроку. Он продолжает идти спиной вперёд."},"E147.5":{"s":"Вы оставляете Амарона продолжать его странное паломничество. Колокольчик на посохе звенит за поворотом."},"E148.1":{"s":"Вы подтверждаете, что чудесное спасение не отменяет прежнего приговора. Судья Сариэль принимает заключение и выдаёт золото за участие в разбирательстве."},"E148.2":{"s":"Вы предлагаете заменить казнь обязательной службой пострадавшей семье, и обе стороны принимают условия. Суд снабжает отряд припасами.","f":"Родные погибшего считают помилование отрицанием их потери и призывают сторонников. В зале суда начинается стычка."},"E148.3":{"s":"{{heroName}} отделяет обязанность Бена ответить за убийство от желания родственников немедленной расправы. Сариэль утверждает решение и награждает отряд золотом.","f":"{{heroName}} предлагает рассмотреть наказание отдельно от чуда, но стороны не принимают общую формулировку. Суд откладывает решение."},"E148.4":{"s":"Бен соглашается на опасную службу под командованием Короля вместо неопределённого ожидания суда. Он вступает в отряд.","f":"Бен отказывается менять судебное решение на военную службу и остаётся перед Сариэлем. Отряд уходит без нового бойца.","v":{"rs":"Бен принимает предложение служить, но взять нового бойца не удаётся. Суд выделяет отряду золото вместо заключённого контракта."}},"E148.5":{"s":"Вы отказываетесь решать дело вместо ангельского суда. Сариэль благодарит за присутствие и возвращается к молчащему Бену."},"E149.1":{"s":"Вы отдаёте Роару тёплую еду и укрытия, пока его дыхание постепенно перестаёт покрывать землю инеем. Хесса благодарит золотом."},"E149.2":{"s":"Магическое пламя прогревает чешую Роара, и он наконец перестаёт дрожать. Хесса делится с отрядом припасами.","f":"Огонь встречается с холодом кристалла резким всплеском, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Ледяной выброс срывает лечение, но никто из допустимых бойцов не получает тяжёлого ранения. Роар остаётся у костра."}},"E149.3":{"s":"{{heroName}} выводит противоположную руну на углях, и голубой кристалл теряет силу внутри Роара. Хесса передаёт золото и припасы.","f":"{{heroName}} не может подобрать руну, не рискуя состоянием Роара. Отряд прекращает попытку без награды."},"E149.4":{"s":"Роар соглашается испытать новую работу — охлаждать погреба в летнюю жару. Довольный наниматель платит отряду золотом за идею.","f":"Хесса отвергает мысль делать из недуга сына ремесло. Роар плотнее заворачивается в плащи, и разговор заканчивается."},"E149.5":{"s":"Вы оставляете Роара у огромного костра. Хесса подбрасывает очередное полено, пока сын жалуется на холод."},"E150.1":{"s":"Вы убеждаете Двена официально освободить Кассара от клятвы, и тёмный рубец на чешуе светлеет. Купец благодарит золотом за решение.","f":"Двен отказывается подписать освобождение, опасаясь лишиться охраны каравана. Кассар остаётся связан прежним словом."},"E150.2":{"s":"Вы находите камень со смытой дороги и объявляете его последним по условиям договора. Двен признаёт завершение клятвы и выдаёт припасы.","f":"Кассар не принимает случайный обломок за настоящий последний камень, и поиски затягиваются. Часть припасов расходуется впустую."},"E150.3":{"s":"{{heroName}} составляет новую клятву так, чтобы охрана завершалась после безопасного прибытия каравана. Кассар произносит её без боли, а Двен платит золотом.","f":"{{heroName}} не находит слов, которые оба сочли бы честным исполнением старого обещания. Рубец на груди Кассара остаётся тёмным."},"E150.4":{"s":"Вы требуете буквального исполнения обещания, и Кассар покорно возвращается к обозу. Двен выдаёт отряду золото, хотя тёмный рубец не исчезает."},"E150.5":{"s":"Вы оставляете купца и посла спорить о последнем камне исчезнувшей дороги. Кассар снова смотрит на рубец, пока Двен разворачивает карту."}});
export { OUTCOMES_E101_E150 };
